// Matrix-style green rain falling down a helix.
// Columns are angular bins around the cylinder; each column runs its own
// trail (head + decaying tail) in a small fixed-point ring buffer.

uniform float speed : 0.2 .. 5.0 = 1.6;      // fall speed (rows per second)
uniform float density : 0.0 .. 1.0 = 0.45;   // fraction of columns active
uniform float trail : 0.05 .. 0.6 = 0.28;    // tail length (fraction of column)
uniform float hue : 0.2 .. 0.45 = 0.33;      // green hue
uniform float glow : 0.2 .. 1.5 = 1.0;       // brightness

const int NCOL = 64;
const int ROWS = 16;
const int NSLOT = NCOL * ROWS;               // 1024

state fixed8 fb[NSLOT];                      // ring buffer of trail energies
state fixed head[NCOL];                      // current head row (float 0..ROWS)
state fixed on[NCOL];                        // column active flag
state fixed ph;                              // scroll phase in rows
state fixed spd;
state fixed dens;
state fixed trlen;
state fixed huef;
state fixed glowf;
state bool inited;

void update() {
  spd = fixed(speed);
  dens = fixed(density);
  trlen = fixed(trail);
  huef = fixed(hue);
  glowf = fixed(glow);
  ph = fract(ph + fixed(dt) * spd);          // integrate scroll rate

  if (!inited) {
    for (int c = 0; c < NCOL; c = c + 1) {
      float h = hash(float(c) * 0.371);
      head[c] = fixed(h * float(ROWS));
      on[c] = step(dens, fixed(hash(float(c) * 0.913 + 7.0))) * fixed(1.0);
    }
    for (int i = 0; i < NSLOT; i = i + 1) fb[i] = fixed8(0.0);
    inited = true;
  }

  // advance each active column's head; paint the head cell
  for (int c = 0; c < NCOL; c = c + 1) {
    if (on[c] > fixed(0.5)) {
      fixed h = head[c] + spd * fixed(dt);
      if (h >= fixed(float(ROWS))) {
        h = h - fixed(float(ROWS));
        // respawn: some columns go dark, dark ones may wake
        on[c] = step(fixed(hash(float(c) * 0.771 + float(frame) * 0.013)), dens);
      }
      head[c] = h;
      int row = int(h);
      if (row >= ROWS) row = ROWS - 1;
      fb[c * ROWS + row] = fixed8(1.0);
    }
  }
}

vec3 shade(Led led) {
  // angular column from the cached atan2 (TURNS, -0.5..0.5)
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);   // 0..1
  fixed cf = ang * fixed(float(NCOL));
  int col = int(cf);
  if (col >= NCOL) col = NCOL - 1;

  // row from height: top of the lamp is row 0
  fixed y = fixed(led.pos.y);                // metres, ~ -0.15..0.15
  fixed rf = (fixed(0.15) - y) * fixed(float(ROWS) / 0.30);
  int row = int(rf);
  if (row < 0) row = 0;
  if (row >= ROWS) row = ROWS - 1;

  // scroll the row lookup by the phase (rows down the column)
  fixed sr = rf - ph;
  sr = sr - fixed(float(int(sr / fixed(float(ROWS))) * ROWS));  // wrap
  if (sr < fixed(0.0)) sr = sr + fixed(float(ROWS));
  int srow = int(sr);
  if (srow >= ROWS) srow = ROWS - 1;

  fixed e = fixed(fb[col * ROWS + srow]);    // this cell's energy
  // decay applied on read: older cells sit further from the head
  fixed d = fixed(float(row)) - head[col];
  if (d < fixed(0.0)) d = d + fixed(float(ROWS));
  fixed fall = fixed(1.0) - clamp(d / trlen, fixed(0.0), fixed(1.0));
  e = e * fall;

  // bright head core + green body
  fixed core = clamp(e * fixed(4.0), fixed(0.0), fixed(1.0));
  vec3 c = hsv2rgb(huef, fixed(0.85), core * glowf);
  return c;
}

